      });

      await expectNoSchools();
    },
  );

  it('rejects a numeric string sectorId without conversion', async () => {
    const sector = await insertSector();

    const response = await agent.post('/schools').send(schoolBody(String(sector.id))).expect(422);
    expect(response.body.message).toContain('sectorId');
